mapper.select:
/* taskInqyDao2010 : 업무일지 목록 조회 */ SELECT RESULT.* FROM ( SELECT T.TASK_ID , T.TASK_SNO , T.TASK_TITLE , TO_CHAR(T.TASK_DT, 'YYYYMMDD') AS TASK_DT , T.TASK_HH , T.TASK_MM , T.PROJ_ID , P.PROJ_TITLE , T.REG_IDX , TO_CHAR(T.REG_DT, 'YYYYMMDD') AS REG_DT , E.EMP_NM , E.ORG_CD , O.ORG_NM , R.RANK_NM , E.RANK_CD , COUNT(*) OVER(PARTITION BY T.TASK_ID) AS ROW_CNT , ROW_NUMBER() OVER(PARTITION BY T.TASK_ID ORDER BY T.TASK_SNO ASC) AS ROW_NUM , COUNT(*) OVER() AS LIST_CNT FROM TASK T INNER JOIN EMP_INFO E ON E.EMP_IDX = T.REG_IDX INNER JOIN ORG O ON O.ORG_CD = E.ORG_CD INNER JOIN RANK R ON R.RANK_CD = E.RANK_CD LEFT OUTER JOIN PROJECT P ON P.PROJ_ID = T.PROJ_ID WHERE T.USE_YN = 'Y'
AND O.ORG_CD = #{orgCd, jdbcType=VARCHAR}
AND REGEXP_REPLACE(LOWER(E.EMP_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND T.TASK_DT >= TO_DATE(#{srchSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
AND T.TASK_DT < TO_DATE(#{srchEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1
) RESULT ORDER BY RESULT.TASK_ID DESC, RESULT.TASK_SNO ASC

/* taskInqyDao3010 : 업무 캘린더 조회 */ SELECT TC.TLDR_ID , TC.TLDR_ID AS ID , TC.TLDR_TITLE AS "TITLE" , TO_CHAR(TO_DATE(TC.TLDR_SDT,'YYYY-MM-DD'), 'YYYY-MM-DD') || ' 00:00:00' AS "START" , TO_CHAR(TO_DATE(TC.TLDR_EDT,'YYYY-MM-DD'), 'YYYY-MM-DD') || ' 24:00:00' AS "END" FROM TASK_CALENDAR TC WHERE 1=1 AND TC.EMP_IDX = #{empIdx, jdbcType=VARCHAR}
AND REGEXP_REPLACE(LOWER(TC.TLDR_TITLE),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND TC.TLDR_DT = TO_CHAR(SYSDATE, 'YYYYMMDD')
ORDER BY TC.TLDR_ID ASC

mapper.delete:
/* taskProcDao1020 : 업무일지 삭제 처리 */
DELETE FROM TASK
WHERE REG_IDX = #{empIdx, jdbcType=VARCHAR}
	AND TASK_DT >= TO_DATE(#{srchDt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
	AND TASK_DT < TO_DATE(#{srchDt, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1

mapper.update:
/* taskProcDao2020 : 업무 캘린더 수정 처리 */
UPDATE TASK_CALENDAR
	SET 		TLDR_TITLE = #{tldrTitle, jdbcType=VARCHAR}
			,	TLDR_CONT = #{tldrCont, jdbcType=VARCHAR}
			,	TLDR_SDT = REPLACE(#{tldrSdt, jdbcType=VARCHAR}, '-')
			,	TLDR_EDT = REPLACE(#{tldrEdt, jdbcType=VARCHAR}, '-')
	WHERE TLDR_ID = #{tldrId, jdbcType=VARCHAR}

